previewCss:
.darma-loader-darma-b16-floppy-disk-write { --accent: var(--loader-color, #1e293b); --accent-2: var(--loader-secondary-color, #22c55e); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b16-floppy-disk-write .darma-loader-darma-b16-floppy-disk-write__body { position: absolute; inset: 4%; border-radius: 5px 12px 5px 5px; background: linear-gradient(150deg, color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); }
.darma-loader-darma-b16-floppy-disk-write .darma-loader-darma-b16-floppy-disk-write__shutter { position: absolute; left: 28%; top: 8%; width: 40%; height: 30%; border-radius: 2px; background: linear-gradient(#cbd5e1, #64748b); animation: darma-loader-darma-b16-floppy-disk-write-floppy-shutter calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.5, 0, .3, 1) infinite; }
.darma-loader-darma-b16-floppy-disk-write .darma-loader-darma-b16-floppy-disk-write__shutter::after { content: ''; position: absolute; left: 58%; top: 10%; width: 26%; height: 80%; border-radius: 2px; background: color-mix(in srgb, #0f172a 65%, transparent); }
.darma-loader-darma-b16-floppy-disk-write .darma-loader-darma-b16-floppy-disk-write__label { position: absolute; left: 16%; right: 16%; bottom: 12%; height: 34%; border-radius: 3px; background: repeating-linear-gradient(color-mix(in srgb, #fff 78%, var(--accent)) 0 26%, color-mix(in srgb, #fff 55%, var(--accent)) 0 34%); overflow: hidden; }
.darma-loader-darma-b16-floppy-disk-write .darma-loader-darma-b16-floppy-disk-write__label::after { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 0; background: color-mix(in srgb, var(--accent-2) 55%, transparent); animation: darma-loader-darma-b16-floppy-disk-write-floppy-write calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b16-floppy-disk-write .darma-loader-darma-b16-floppy-disk-write__led { position: absolute; right: 10%; top: 12%; width: 8%; height: 8%; border-radius: 50%; background: var(--accent-2); animation: darma-loader-darma-b16-floppy-disk-write-floppy-led calc(var(--loader-speed, 1s) * .6) steps(1, end) infinite; }
@keyframes darma-loader-darma-b16-floppy-disk-write-floppy-shutter { 0%, 8% { transform: translateX(0); } 24%, 76% { transform: translateX(-46%); } 92%, 100% { transform: translateX(0); } }
@keyframes darma-loader-darma-b16-floppy-disk-write-floppy-write { 0%, 20% { width: 0; } 80%, 100% { width: 100%; } }
@keyframes darma-loader-darma-b16-floppy-disk-write-floppy-led { 0%, 49% { opacity: 1; box-shadow: 0 0 10px var(--accent-2); } 50%, 100% { opacity: .2; box-shadow: none; } }

